        try c.encode(self.video, forKey: .video)
        try c.encode(self.audio, forKey: .audio)
        try c.encode(self.subtitles, forKey: .subtitles)
    }
    public struct Format: Codable, Sendable, Hashable {
        public var name: String
        public var durationSeconds: Double?
        public var startSeconds: Explicit<Double>
        public var bitRate: Int64?
        public init(name: String, durationSeconds: Double?, startSeconds: Explicit<Double> = .omitted, bitRate: Int64?) {
            self.name = name
            self.durationSeconds = durationSeconds
            self.startSeconds = startSeconds
            self.bitRate = bitRate
        }
        private enum CodingKeys: String, CodingKey {
            case name = "name"
            case durationSeconds = "durationSeconds"
            case startSeconds = "startSeconds"
            case bitRate = "bitRate"
        }
        public init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            self.name = try c.decode(String.self, forKey: .name)
            self.durationSeconds = try c.decodeIfPresent(Double.self, forKey: .durationSeconds)
            self.startSeconds = try !c.contains(.startSeconds) ? .omitted : c.decodeNil(forKey: .startSeconds) ? .null : .value(c.decode(Double.self, forKey: .startSeconds))
            self.bitRate = try c.decodeIfPresent(Int64.self, forKey: .bitRate)
        }
        public func encode(to encoder: any Encoder) throws {
            var c = encoder.container(keyedBy: CodingKeys.self)
            try c.encode(self.name, forKey: .name)
            try c.encode(self.durationSeconds, forKey: .durationSeconds)
            switch startSeconds {
            case .omitted: break
            case .null: try c.encodeNil(forKey: .startSeconds)
            case .value(let value): try c.encode(value, forKey: .startSeconds)
            }
            try c.encode(self.bitRate, forKey: .bitRate)
        }
    }
}

